/**
 * Migrate from V2 of the config to V3
 *
 * Exported for testing
 */
export function migrateConfigV2to3(loadedConfig: any) {
	if (!Array.isArray(loadedConfig._credentials)) return
	const credentials: Record<string, PersistentCredentials> = {}
	for (const oldCredential of loadedConfig._credentials) {
		const userId = oldCredential?.userId ?? oldCredential?.credentialInfo?.userId
		if (!userId) continue
		const {mailAddress, userId: legacyUserId, ...rest} = oldCredential
		credentials[userId] = {
			...rest,
			credentialInfo: oldCredential.credentialInfo ?? {
				login: typeof mailAddress === "string" && mailAddress.includes("@") ? mailAddress : userId,
				userId,
				type: typeof mailAddress === "string" && mailAddress.includes("@") ? "internal" : "external",
			},
		}
	}
	loadedConfig._credentials = credentials
}

